start_time=$(date +%s)

for d in 0.1 0.2 0.3 0.4
# for d in 0.3
	do
	# Loop over the pairs and extract each value
	for pair in "${pairs[@]}"; do
		# Split the pair into two values
		IFS=' ' read -r n_items k_responses <<< "$pair"
		
		n_items=${n_items%.*}
		k_responses=${k_responses%.*}
		echo "Value1: $n_items, Value2: $k_responses"
	
		python categorical_sample.py --n_items=${n_items} --k_responses=${k_responses} --num_samples=1000 --distortion=${d} --use_pickle=true --compression="lz4" --exp_dir=../../../../data/ptest_arr_dices/
